#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> width(n), height(n), startY(n);
    int curY = 0, maxW = 0;

    for (int i = 0; i < n; ++i) {
        int k;
        cin >> k;
        int minX = 0, maxX = 0, minY = 0, maxY = 0;
        bool first = true;
        for (int j = 0; j < k; ++j) {
            int x, y;
            cin >> x >> y;
            if (first) {
                minX = maxX = x;
                minY = maxY = y;
                first = false;
            } else {
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
            }
        }
        int w = maxX - minX + 1;
        int h = maxY - minY + 1;
        width[i] = w;
        height[i] = h;
        startY[i] = curY;
        curY += h;
        if (w > maxW) maxW = w;
    }

    cout << maxW << ' ' << curY << '\n';
    for (int i = 0; i < n; ++i) {
        cout << "0 " << startY[i] << " 0 0\n";
    }
    return 0;
}
